import { useEffect, useState } from 'react'
import { get, size } from 'lodash'
import { connect } from 'react-redux'
import { Container, CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import policyActions from '../../../../../redux/policy/action'
import PolicyDocumentCard from '../../components/PolicyDocumentCard'
import { PolicyDocumentStyle } from './index.style'
import ShowSnackbar from '../../../../../components/ShowNotification'

const { getInsuranceDocs } = policyActions

function PolicyDocuments (props) {
  const { getInsuranceDocs, match, insuranceLoader, insuranceDocsData } = props
  const [showBar, setShowBar] = useState(null)
  const [barMsg, setBarMsg] = useState('')

  useEffect(() => {
    const policyId = get(match, 'params.policyId', '')
    getInsuranceDocs(policyId.replace(/-/g, ''))
  }, [getInsuranceDocs, match])

  const handleShowSnackbar = (isShow, text) => {
    setShowBar(isShow)
    setBarMsg(text)
    setTimeout(() => {
      setShowBar(false)
    }, 4000)
  }

  const getTitle = (title, textAlign = 'left') => (
    <CustomText
      color={AgentColorPallette.fontDarkerGrey}
      bottom='0'
      weight={800}
      textAlign={textAlign}
      className='document-title'
    >
      {title}
    </CustomText>
  )

  return (
    <Container
      title={LANG_STRINGS.policyDocuments}
      loader={insuranceLoader}
      displayBackButton
      hideBottomTabs
    >
      <PolicyDocumentStyle>
        {!size(insuranceDocsData.main_documents) && !size(insuranceDocsData.additional_documents) && getTitle(LANG_STRINGS.documentsUnavailable, 'center')}

        {!!size(insuranceDocsData.main_documents) && getTitle(LANG_STRINGS.mainDocuments)}
        {
          !!size(insuranceDocsData.main_documents) && insuranceDocsData.main_documents.map((doc, index) => (
            <PolicyDocumentCard
              key={`main-documents-${index}`}
              name={doc.name}
              id={`policy_certificate${index + 1}`}
              size={doc.size}
              url={doc.url}
              onShowSnackbar={handleShowSnackbar}
            />
          ))
        }
        {!!size(insuranceDocsData.additional_documents) && getTitle(LANG_STRINGS.additionalDocument)}
        {
          !!size(insuranceDocsData.additional_documents) && insuranceDocsData.additional_documents.map((doc, index) => (
            <PolicyDocumentCard
              onShowSnackbar={handleShowSnackbar}
              key={`addition-documents-${index}`}
              id='other_documents'
              name={doc.name}
              size={doc.size}
              url={doc.url}
            />
          ))
        }
        {!!size(insuranceDocsData.endorsement_documents) && getTitle(LANG_STRINGS.endorsementDocuments)}
        {
          !!size(insuranceDocsData.endorsement_documents) && insuranceDocsData.endorsement_documents.map((doc, index) => (
            <PolicyDocumentCard
              onShowSnackbar={handleShowSnackbar}
              key={`endorsement-documents-${index}`}
              id={`endorsement_document${index + 1}`}
              name={doc.name}
              size={doc.size}
              url={doc.url}
            />
          ))
        }
        {
          !!size(insuranceDocsData.cancellation_documents) && getTitle(LANG_STRINGS.cancellationDocuments)
        }
        {
          !!size(insuranceDocsData.cancellation_documents) && insuranceDocsData.cancellation_documents.map((doc, index) => (
            <PolicyDocumentCard
              onShowSnackbar={handleShowSnackbar}
              key={`cancellation-documents-${index}`}
              id={`cancellation_document${index + 1}`}
              name={doc.name}
              size={doc.size}
              url={doc.url}
            />
          ))
        }
      </PolicyDocumentStyle>
      {
        showBar && (<ShowSnackbar show={showBar} text={barMsg} />)
      }
    </Container>
  )
}

export default connect(
  state => ({
    insuranceLoader: state.Loading.GET_INSURANCE_DOCS,
    insuranceDocsData: state.Policy.insuranceDocsData,
    insuranceDocStatus: state.Policy.insuranceDocStatus
  }),
  {
    getInsuranceDocs
  }
)(PolicyDocuments)
